use super::*;
use digimon_engine::{debug_runner::{DebugRunner,make_test_card},enums::GamePhase,action::space::PASS};
fn fixture()->Game {let mut c=make_test_card("EXPENSIVE","Expensive");c.play_cost=20;let mut r=DebugRunner::builder().add_card(c).deck(0,&["EXPENSIVE";20]).deck(1,&["EXPENSIVE";20]).hand(0,&["EXPENSIVE"]).start();r.skip_mulligan();r.game.current_phase=GamePhase::Main;r.game.memory=0;r.game}
fn flagged()->StepAction {serde_yml::from_str("pass: {sim_only: true}").expect("explicit pass schema")}
#[test] fn explicit_forced_main_pass_has_zero_wire_rows(){let g=fixture();let a=flagged();let row=classify_scenario_action(&g,0,0,&a,PASS).unwrap();assert!(matches!(row,LoweredStep::SimOnlyAction(PASS)));assert_eq!(row.dcgo_wire_rows(),0);}
#[test] fn ordinary_pass_stays_shared_even_when_forced(){let g=fixture();let a=serde_yml::from_str("pass: {}").unwrap();assert!(matches!(classify_scenario_action(&g,0,0,&a,PASS).unwrap(),LoweredStep::Action(PASS)));}
#[test] fn pass_with_another_legal_action_cannot_be_hidden(){let mut g=fixture();g.memory=10;assert!(classify_scenario_action(&g,0,0,&flagged(),PASS).unwrap_err().contains("only legal"));}
#[test] fn wrong_actor_and_nonmain_phases_are_rejected(){let mut g=fixture();assert!(classify_scenario_action(&g,0,1,&flagged(),PASS).is_err());for phase in [GamePhase::Breeding,GamePhase::EndOfTurnAction]{g.current_phase=phase;assert!(classify_scenario_action(&g,0,0,&flagged(),PASS).is_err());}}
#[test] fn pending_selection_is_not_a_forced_main_pass(){let mut g=fixture();g.pending_selection=Some(digimon_engine::selection::PendingSelection { card_choice: None,kind:digimon_engine::selection::SelectionKind::EffectChoice,selecting_player:0,previous_phase:GamePhase::Main,valid_action_ids:vec![PASS],is_optional:true,prompt:"pending".into(),effect_choices:None,source_card:g.players[0].hand[0].handle(),source_permanent:None,source_kind:digimon_engine::enums::EffectSourceKind::Digimon,callback:Box::new(|_,_|{}),on_decline:None,zone_owner:None});assert!(classify_scenario_action(&g,0,0,&flagged(),PASS).is_err());}
#[test] fn unsupported_identity_is_not_evidence_of_no_actions(){let mut g=fixture();g.players[0].hand[0].is_opaque_placeholder=true;assert!(classify_scenario_action(&g,0,0,&flagged(),PASS).is_err());}
#[test] fn explicit_pass_codec_roundtrips_and_rejects_unknown_fields(){let a=flagged();let s=serde_yml::to_string(&a).unwrap();assert_eq!(serde_yml::from_str::<StepAction>(&s).unwrap(),a);assert!(serde_yml::from_str::<StepAction>("pass: {sim_only: true, dcgo_only: true}").is_err());assert!(serde_yml::from_str::<StepAction>("pass: {sim_only: 1}").is_err());}
